const data = msg.payload;

// Werte aufbereiten
const soc = data.soc != null ? data.soc : (data.battery_level || 0);
const voltage = data.voltage || 0;
const current = data.current || 0;
const power = data.power || (voltage * current);
const temp = data.temperatures && data.temperatures.length > 0 ? data.temperatures[0] : null;
const cycles = data.cycles || 0;

// Node-RED Dashboard / Status
node.status({
  fill: soc > 20 ? "green" : "red",
  shape: "dot",
  text: `${soc}% | ${voltage.toFixed(2)}V`
});

// Mehrere Topics für separate Dashboard-Anzeigen
const topics = [
  { topic: "dashboard/bms/voltage", payload: voltage, unit: "V" },
  { topic: "dashboard/bms/current", payload: current, unit: "A" },
  { topic: "dashboard/bms/power", payload: power, unit: "W" },
  { topic: "dashboard/bms/soc", payload: soc, unit: "%" },
  { topic: "dashboard/bms/temperature", payload: temp, unit: "°C" },
  { topic: "dashboard/bms/capacity", payload: data.capacity || data.design_capacity || 0, unit: "Ah" },
  { topic: "dashboard/bms/cycles", payload: data.cycles || 0, unit: "" },
];

// Optional: Zellenspannungen
if (data.cell_voltages && Array.isArray(data.cell_voltages)) {
  const cells = data.cell_voltages.map((v, i) => ({
    topic: `dashboard/bms/cell/${i + 1}`,
    payload: v,
    unit: "V"
  }));
  topics.push(...cells);
}

return topics;

const data = msg.payload;

// InfluxDB 2.x kompatibles Format
// (über node-red-contrib-influxdb)
const fields = {
  voltage: Number(data.voltage || 0),
  current: Number(data.current || 0),
  power: Number(data.power || data.voltage * data.current || 0),
  soc: Number(data.soc != null ? data.soc : data.battery_level || 0),
  temperature: data.temperatures && data.temperatures.length > 0 ? Number(data.temperatures[0]) : null,
  capacity: Number(data.capacity || data.design_capacity || 0),
  cycles: Number(data.cycles || 0)
};

msg.payload = {
  measurement: "bms_jbd",
  tags: { device: "jbd_battery" },
  fields: fields
};

return msg;

// Erzeugt einen Sensor-Status wenn Daten ankommen
// Nützlich für Node-RED Dashboard / Home Assistant
const heartbeat = {
  topic: "bms/jbd/heartbeat",
  payload: Date.now(),
  online: true
};

// Home Assistant Auto-Discovery
// (kommentiert — aktivieren wenn benötigt)
// const discovery = {
//   topic: "homeassistant/sensor/jbd_bms_voltage/config",
//   payload: JSON.stringify({
//     name: "JBD BMS Spannung",
//     state_topic: "bms/jbd/data",
//     value_template: "{{ value_json.voltage }}",
//     unit_of_measurement: "V",
//     device_class: "voltage"
//   })
// };

return heartbeat;
